// Generated by AI (UnitTest MCP)
use std::collections::HashSet;

use serde_json::{json, Value};

use crate::{ConformanceRecord, Lodestar, Result, TaskReceipt, Verdict};

impl Lodestar {
    /// Build an evidence bundle from a merge that already landed (ADR-0058).
    ///
    /// This is the point of the whole decision: the agent names the commit that
    /// carried its work and the plane verifies it, instead of the agent
    /// assembling a description of work it has already finished at the moment it
    /// cares least. Every field below is derived from what git reports, so there
    /// is nothing for a caller to get wrong and nothing to embellish.
    ///
    /// It does **not** complete the task. Conformance still judges the result
    /// (ADR-0058 decision 3) and somebody still has to submit it (decision 5) —
    /// this removes the requirement to *manufacture* evidence, not the
    /// requirement to *submit* it. A verb that closed the task here would record
    /// a completion nobody attested, which is the failure ADR-0009 exists to
    /// prevent.
    pub fn merge_evidence(
        &self,
        task_id: &str,
        commit: &str,
        agent: &str,
    ) -> Result<crate::ConformanceEvidence> {
        let root = self.workspace_root.as_deref().ok_or_else(|| {
            crate::LodestarError::Invalid(
                "this server was not told which checkout it serves, so it cannot verify a merge; \
                 set MINDLEAK_WORKSPACE or complete with an evidence bundle instead"
                    .to_string(),
            )
        })?;
        let agent = self.resolve_agent(agent)?;
        let task = self
            .store
            .get_task(task_id)?
            .ok_or_else(|| crate::LodestarError::NotFound(task_id.to_string()))?;
        if task.owner.as_deref() != Some(agent) {
            return Err(crate::LodestarError::Invalid(format!(
                "{task_id} is not held by {agent}; a merge proves who shipped the work, \
                 not who may claim credit for it"
            )));
        }

        // The integration branch is the one a merge has to be reachable from.
        // Resolved rather than named: `origin/main` when the checkout has it,
        // because under ADR-0038 nobody checks `main` out and the local branch
        // is whatever the clone left behind. This is still not "whatever branch
        // I am on" — it is the protected branch's remote-tracking ref, which is
        // exactly what ADR-0058 means by a merge that passed review and CI.
        let scope = self.store.task_scope(task_id)?;
        let root_path = std::path::Path::new(root);
        let integration = crate::merge::integration_ref(root_path);
        let proof = crate::merge::verify_merge(root_path, commit, integration, &scope.paths)?;

        let intent = format!("intent:{}", proof.commit);
        let changed_node_ids: Vec<String> = proof
            .changed_paths
            .iter()
            .map(|path| format!("artifact:{path}"))
            .collect();
        let mut provenance = vec![crate::EvidenceProvenance {
            source_id: format!("agent:{agent}"),
            target_id: intent.clone(),
            relation: "observed".to_string(),
        }];
        provenance.extend(
            changed_node_ids
                .iter()
                .map(|node| crate::EvidenceProvenance {
                    source_id: intent.clone(),
                    target_id: node.clone(),
                    relation: "refactored".to_string(),
                }),
        );

        let started_at = task.claim_started_at.unwrap_or_else(crate::now_unix);
        Ok(crate::ConformanceEvidence {
            schema_version: 1,
            task_id: Some(task_id.to_string()),
            agent_id: agent.to_string(),
            started_at,
            ended_at: crate::now_unix(),
            summary: format!(
                "agent={agent}; verified merge {} touching {} path(s) inside the task's declared scope",
                proof.commit,
                proof.changed_paths.len()
            ),
            changed_node_ids,
            failed_node_ids: Vec::new(),
            execution_ids: Vec::new(),
            successful_execution_ids: Vec::new(),
            commit_ids: vec![intent],
            ledger_act_ids: Vec::new(),
            provenance,
        })
    }

    /// Build an evidence bundle from one Lodestar-internal ledger act (ADR-0110)
    /// instead of refusing the completion outright because the act touched no
    /// MindLeak node.
    ///
    /// Unlike `merge_evidence`, this never leaves the process: each of the four
    /// eligible [`crate::LedgerActKind`] variants is already durably recorded,
    /// with its own actor and timestamp, in Lodestar's own store. The lookup
    /// itself is the verification — there is nothing for MindLeak to attest
    /// that Lodestar does not already know first-hand.
    ///
    /// Conformance still judges the result exactly as it does for a merge
    /// (ADR-0058 decision 3, extended by ADR-0110 decision 4): this only
    /// supplies evidence that something real and attributable happened: it
    /// does not grant alignment by itself, and does not complete the task.
    pub fn ledger_act_evidence(
        &self,
        task_id: &str,
        kind: crate::LedgerActKind,
        act_id: &str,
        agent: &str,
    ) -> Result<crate::ConformanceEvidence> {
        let agent = self.resolve_agent(agent)?;
        let task = self
            .store
            .get_task(task_id)?
            .ok_or_else(|| crate::LodestarError::NotFound(task_id.to_string()))?;
        if task.owner.as_deref() != Some(agent) {
            return Err(crate::LodestarError::Invalid(format!(
                "{task_id} is not held by {agent}; a ledger act proves who performed it, \
                 not who may claim credit for it"
            )));
        }

        let (recorded_actor, occurred_at) = match kind {
            crate::LedgerActKind::DesignRegistered => {
                let item = self
                    .store
                    .get_design_item(act_id)?
                    .ok_or_else(|| crate::LodestarError::NotFound(act_id.to_string()))?;
                let actor = item.proposed_by.ok_or_else(|| {
                    crate::LodestarError::Invalid(format!(
                        "{act_id} has no recorded proposer to verify against"
                    ))
                })?;
                (actor, item.created_at)
            }
            crate::LedgerActKind::DesignDecided => {
                let item = self
                    .store
                    .get_design_item(act_id)?
                    .ok_or_else(|| crate::LodestarError::NotFound(act_id.to_string()))?;
                let actor = item.decided_by.ok_or_else(|| {
                    crate::LodestarError::Invalid(format!(
                        "{act_id} has not been decided yet, so it has no recorded decider"
                    ))
                })?;
                (actor, item.updated_at)
            }
            crate::LedgerActKind::WaiverGranted => {
                let waiver = self
                    .store
                    .waiver(act_id)?
                    .ok_or_else(|| crate::LodestarError::NotFound(act_id.to_string()))?;
                (waiver.approved_by, waiver.created_at)
            }
            crate::LedgerActKind::ConstitutionAmended => {
                let amendment = self
                    .store
                    .amendment(act_id)?
                    .ok_or_else(|| crate::LodestarError::NotFound(act_id.to_string()))?;
                (amendment.amended_by, amendment.created_at)
            }
            crate::LedgerActKind::GoalSuperseded => {
                // The goal must exist AND carry a recorded supersession. A
                // clause retired before ADR-0144 has neither actor nor
                // timestamp, and the honest answer there is a refusal naming
                // the reason -- not this agent's id standing in for whoever
                // actually did it.
                if self.store.get_goal(act_id)?.is_none() {
                    return Err(crate::LodestarError::NotFound(act_id.to_string()));
                }
                self.store.goal_supersession(act_id)?.ok_or_else(|| {
                    crate::LodestarError::Invalid(format!(
                        "{act_id} has no recorded supersession to verify against; it is either \
                         still active or was superseded before the actor was recorded (ADR-0144)"
                    ))
                })?
            }
        };

        if recorded_actor != agent {
            return Err(crate::LodestarError::Invalid(format!(
                "{act_id}'s recorded actor {recorded_actor} does not match {agent}; \
                 a ledger act is evidence only for the agent who actually performed it"
            )));
        }
        let claim_started_at = task.claim_started_at.unwrap_or(occurred_at);
        if occurred_at < claim_started_at {
            return Err(crate::LodestarError::Invalid(format!(
                "{act_id} was recorded at {occurred_at}, before the claim opened at \
                 {claim_started_at}; it cannot be evidence for work this claim did not yet authorise"
            )));
        }

        let node_id = format!("ledger_act:{}:{act_id}", kind.as_str());
        let provenance = vec![crate::EvidenceProvenance {
            source_id: format!("agent:{agent}"),
            target_id: node_id.clone(),
            relation: "observed".to_string(),
        }];

        Ok(crate::ConformanceEvidence {
            schema_version: 1,
            task_id: Some(task_id.to_string()),
            agent_id: agent.to_string(),
            started_at: claim_started_at,
            ended_at: crate::now_unix(),
            summary: format!(
                "agent={agent}; verified ledger act {} ({act_id})",
                kind.as_str()
            ),
            changed_node_ids: Vec::new(),
            failed_node_ids: Vec::new(),
            execution_ids: Vec::new(),
            successful_execution_ids: Vec::new(),
            commit_ids: Vec::new(),
            ledger_act_ids: vec![node_id],
            provenance,
        })
    }

    /// Render a task's durable conformance record chain as committed-friendly,
    /// portable proof-of-work (ADR-0031): each check's stable id, verdict, acting
    /// agent, claim window, and evidence summary. Optionally write it to `path` so
    /// the proof leaves the local ledger for review, CI, and audit. Deterministic
    /// and model-free — it only reads the durable audit trail (mirrors
    /// [`export_constitution`](Self::export_constitution)).
    pub fn export_evidence(&self, task_id: &str, path: Option<&str>) -> Result<String> {
        let records = self.conformance_history(task_id)?;
        let markdown = render_evidence(task_id, &records);
        if let Some(destination) = path {
            if let Some(parent) = std::path::Path::new(destination).parent() {
                std::fs::create_dir_all(parent)?;
            }
            std::fs::write(destination, &markdown)?;
        }
        Ok(markdown)
    }

    /// The conformance record a task closed on, summarised for a reader who is
    /// looking at the completion rather than auditing the chain.
    ///
    /// `None` when the task has no record at all — which is itself worth seeing,
    /// and is not the same as a record that proved nothing.
    pub fn task_receipt(&self, task_id: &str) -> Result<Option<TaskReceipt>> {
        Ok(self
            .conformance_history(task_id)?
            .last()
            .map(summarise_receipt))
    }

    /// Render the repo-wide conformance manifest — the machine-checkable artifact
    /// the CI conformance gate consumes (ADR-0031): the governed code-node set plus,
    /// per task, its latest verdict and the governed nodes an aligned check covered.
    /// The gate fails a merge when changed governed code has no aligned receipt.
    /// Optionally written to `path`. Deterministic and model-free.
    pub fn export_conformance_manifest(&self, path: Option<&str>) -> Result<String> {
        let governed = self.store.governed_node_ids()?;
        let governed_set: HashSet<&str> = governed.iter().map(String::as_str).collect();
        let mut receipts = Vec::new();
        for task in self.board(true)? {
            let records = self.conformance_history(&task.id)?;
            let Some(latest) = records.last() else {
                continue;
            };
            let bundle: Value = serde_json::from_str(&latest.evidence).unwrap_or(Value::Null);
            let covered: Vec<&str> = bundle
                .get("changed_node_ids")
                .and_then(Value::as_array)
                .map(|ids| {
                    ids.iter()
                        .filter_map(Value::as_str)
                        .filter(|id| governed_set.contains(id))
                        .collect()
                })
                .unwrap_or_default();
            receipts.push(json!({
                "task_id": task.id,
                "verdict": verdict_label(&latest.verdict),
                "covered_nodes": covered,
            }));
        }
        let manifest = json!({
            "schema": 1,
            "generated_at": crate::now_unix(),
            "governed_nodes": governed,
            "receipts": receipts,
        });
        let rendered = serde_json::to_string_pretty(&manifest).unwrap_or_else(|_| "{}".to_string());
        if let Some(destination) = path {
            if let Some(parent) = std::path::Path::new(destination).parent() {
                std::fs::create_dir_all(parent)?;
            }
            std::fs::write(destination, &rendered)?;
        }
        Ok(rendered)
    }
}

/// The canonical lowercase label for a verdict, taken from its `Serialize` impl so
/// there is no hand-maintained match to drift from the enum.
fn verdict_label(verdict: &Verdict) -> String {
    serde_json::to_value(verdict)
        .ok()
        .and_then(|value| value.as_str().map(str::to_string))
        .unwrap_or_else(|| "unknown".to_string())
}

/// How many nodes an evidence bundle covered, read from the stored blob.
///
/// Counts `ledger_act_ids` alongside `changed_node_ids` (ADR-0110): a verified
/// ledger act is exactly as real a covered thing as a changed MindLeak node,
/// so an aligned receipt built entirely from one must still be able to
/// `affirm` -- otherwise a genuinely evidence-backed completion would read as
/// having affirmed nothing, the same hollow shape this count exists to catch.
fn covered_node_count(record: &ConformanceRecord) -> usize {
    let Ok(bundle) = serde_json::from_str::<Value>(&record.evidence) else {
        return 0;
    };
    let array_len = |field: &str| {
        bundle
            .get(field)
            .and_then(Value::as_array)
            .map(Vec::len)
            .unwrap_or(0)
    };
    array_len("changed_node_ids") + array_len("ledger_act_ids")
}

/// Summarise one record for a reader looking at a completion.
fn summarise_receipt(record: &ConformanceRecord) -> TaskReceipt {
    let covered_nodes = covered_node_count(record);
    TaskReceipt {
        conformance_id: record.id,
        verdict: record.verdict,
        covered_nodes,
        checked_at: record.checked_at,
        // Agreement about nothing is not proof: an `aligned` verdict over a
        // bundle that touched no node affirms as little as a `needs_human` one.
        affirms: matches!(record.verdict, Verdict::Aligned) && covered_nodes > 0,
    }
}

/// Render the conformance chain as committed-friendly markdown. Each row resolves
/// back to the durable record by its stable `id`; the evidence summary carries the
/// provenance counts (executions, commits, changed nodes) behind the verdict.
fn render_evidence(task_id: &str, records: &[ConformanceRecord]) -> String {
    let mut out = format!("# Conformance evidence for `{task_id}`\n\n");
    out.push_str(
        "> Generated by Lodestar (ADR-0031). Portable proof-of-work: each row resolves to a \
         durable, provenance-bearing evidence record. Do not edit by hand.\n\n",
    );
    if records.is_empty() {
        out.push_str("_No conformance records: this task never reached a checked completion._\n");
        return out;
    }
    out.push_str("| Check | Verdict | Covered | Agent | Window (unix) | Checked | Summary |\n");
    out.push_str("|--:|---|--:|---|---|--:|---|\n");
    for record in records {
        let bundle: Value = serde_json::from_str(&record.evidence).unwrap_or(Value::Null);
        let agent = bundle
            .get("agent_id")
            .and_then(Value::as_str)
            .unwrap_or("-");
        let started = bundle
            .get("started_at")
            .and_then(Value::as_i64)
            .unwrap_or(0);
        let ended = bundle.get("ended_at").and_then(Value::as_i64).unwrap_or(0);
        let summary = bundle.get("summary").and_then(Value::as_str).unwrap_or("");
        // Covered nodes sit beside the verdict rather than inside the summary
        // prose: a receipt that proved nothing about any code is the thing a
        // reader most needs to see, and it must not need parsing to find.
        out.push_str(&format!(
            "| {} | {} | {} | {} | {}-{} | {} | {} |\n",
            record.id,
            verdict_label(&record.verdict),
            covered_node_count(record),
            agent,
            started,
            ended,
            record.checked_at,
            summary,
        ));
    }
    out.push('\n');
    for record in records {
        if !record.findings.trim().is_empty() {
            out.push_str(&format!(
                "- **#{} {}** — {}\n",
                record.id,
                verdict_label(&record.verdict),
                record.findings,
            ));
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use crate::facade::test_support::engine;
    use crate::store::ConformanceAudit;
    use crate::{GoalKind, TaskStatus, Verdict};

    /// Bug: a completion said nothing about whether its evidence affirmed the
    /// work. Measured over this repository, 57 of 101 `done` tasks rested on a
    /// `drift`/`needs_human` verdict or an `aligned` one covering no nodes, and
    /// on the board every one of them read exactly like a task whose evidence
    /// proved something. Impact: the conformance chain is described as the only
    /// trustworthy proof the agents did the sanctioned work, and the surface
    /// people actually read could not tell proof from its absence. Fix: derive
    /// the receipt at read time and carry `affirms` with the completion.
    #[test]
    fn a_receipt_over_an_empty_bundle_does_not_affirm_however_it_was_graded() {
        let engine = engine();
        let goal = engine
            .define_goal(GoalKind::Objective, "Ship", "ship it", None)
            .unwrap();
        let checked = |title: &str, verdict: Verdict, status: TaskStatus, evidence: &str| {
            let task = engine.create_task(&goal.id, title, "done").unwrap();
            assert!(engine.claim_task(&task.id, "agent-a", 600).unwrap());
            assert!(engine
                .store
                .record_conformance_and_transition(
                    &task.id,
                    "agent-a",
                    ConformanceAudit {
                        evidence_schema_version: 1,
                        evidence,
                        verdict,
                        findings: "",
                    },
                    status,
                    crate::now_unix(),
                )
                .unwrap());
            engine.task_receipt(&task.id).unwrap().expect("a receipt")
        };

        let proved = checked(
            "Proved",
            Verdict::Aligned,
            TaskStatus::Done,
            r#"{"changed_node_ids":["artifact:src/lib.rs","artifact:src/db.rs"]}"#,
        );
        assert_eq!(proved.covered_nodes, 2);
        assert!(proved.affirms, "aligned over real nodes affirms");

        // The sharp case: agreement about nothing is not proof.
        let hollow = checked(
            "Hollow",
            Verdict::Aligned,
            TaskStatus::Done,
            r#"{"changed_node_ids":[]}"#,
        );
        assert_eq!(hollow.covered_nodes, 0);
        assert!(
            !hollow.affirms,
            "an aligned verdict over an empty bundle affirms nothing"
        );

        let unresolved = checked(
            "Unresolved",
            Verdict::NeedsHuman,
            TaskStatus::InReview,
            r#"{"changed_node_ids":["artifact:src/lib.rs"]}"#,
        );
        assert_eq!(unresolved.covered_nodes, 1);
        assert!(
            !unresolved.affirms,
            "a verdict that deferred to a human has not affirmed anything"
        );
    }

    #[test]
    fn a_task_with_no_record_at_all_has_no_receipt_rather_than_an_empty_one() {
        // Distinct from a receipt that proved nothing, and worth seeing as such.
        let engine = engine();
        assert!(engine.task_receipt("task:none").unwrap().is_none());
    }

    #[test]
    fn export_of_a_task_without_records_is_explicit_not_empty() {
        // A task that never reached a checked completion must produce a clear,
        // human-readable artifact — not an empty file that looks like "no proof
        // because nothing was checked" is indistinguishable from a write failure.
        let engine = engine();
        let markdown = engine.export_evidence("task:none", None).unwrap();
        assert!(markdown.contains("task:none"));
        assert!(markdown.contains("never reached a checked completion"));
    }

    #[test]
    fn manifest_of_an_empty_ledger_is_valid_and_empty() {
        let engine = engine();
        let json = engine.export_conformance_manifest(None).unwrap();
        let parsed: serde_json::Value = serde_json::from_str(&json).unwrap();
        assert!(parsed["governed_nodes"].as_array().unwrap().is_empty());
        assert!(parsed["receipts"].as_array().unwrap().is_empty());
        assert_eq!(parsed["schema"], 1);
    }

    // ADR-0110: a Lodestar ledger act is independently verifiable evidence.
    mod ledger_act_evidence {
        use super::*;
        use crate::design::design_id_from_path;
        use crate::LedgerActKind;

        /// A claimed task under a fresh objective goal, owned by `agent`.
        fn claimed_task(engine: &crate::Lodestar, agent: &str) -> String {
            let goal = engine
                .define_goal(GoalKind::Objective, "Ship", "ship it", None)
                .unwrap();
            let task = engine
                .create_task(&goal.id, "Ledger act task", "done")
                .unwrap();
            assert!(engine.claim_task(&task.id, agent, 600).unwrap());
            task.id
        }

        /// Regression for the `covered_node_count`/`affirms` fix alongside this
        /// feature: a receipt built entirely from a verified ledger act (no
        /// MindLeak node touched at all) must still be able to affirm, or a
        /// genuinely aligned, evidence-backed completion reads as hollow.
        #[test]
        fn a_ledger_act_only_receipt_affirms_even_though_it_touches_no_changed_node() {
            let engine = engine();
            let task_id = claimed_task(&engine, "agent-a");
            assert!(engine
                .store
                .record_conformance_and_transition(
                    &task_id,
                    "agent-a",
                    ConformanceAudit {
                        evidence_schema_version: 1,
                        evidence: r#"{"ledger_act_ids":["ledger_act:design_registered:design:0001"]}"#,
                        verdict: Verdict::Aligned,
                        findings: "",
                    },
                    TaskStatus::Done,
                    crate::now_unix(),
                )
                .unwrap());
            let receipt = engine.task_receipt(&task_id).unwrap().expect("a receipt");
            assert_eq!(receipt.covered_nodes, 1);
            assert!(
                receipt.affirms,
                "an aligned verdict built from a real ledger act affirms, even with no changed MindLeak node"
            );
        }

        #[test]
        fn succeeds_for_a_design_registration_the_claiming_agent_made() {
            let engine = engine();
            let item = engine
                .register_design("docs/adr/0001-test.md", "Test", "summary", Some("agent-a"))
                .unwrap();
            let task_id = claimed_task(&engine, "agent-a");

            let evidence = engine
                .ledger_act_evidence(
                    &task_id,
                    LedgerActKind::DesignRegistered,
                    &item.id,
                    "agent-a",
                )
                .unwrap();
            assert_eq!(
                evidence.ledger_act_ids,
                vec![format!("ledger_act:design_registered:{}", item.id)]
            );
            assert!(evidence.changed_node_ids.is_empty());
            assert_eq!(evidence.provenance.len(), 1);
            assert_eq!(evidence.task_id.as_deref(), Some(task_id.as_str()));
        }

        #[test]
        fn succeeds_for_a_design_decision_the_claiming_agent_made() {
            let engine = engine();
            let item = engine
                .register_design("docs/adr/0002-test.md", "Test", "summary", Some("agent-b"))
                .unwrap();
            let item = engine.accept_design(&item.id, "agent-a").unwrap();
            let task_id = claimed_task(&engine, "agent-a");

            let evidence = engine
                .ledger_act_evidence(&task_id, LedgerActKind::DesignDecided, &item.id, "agent-a")
                .unwrap();
            assert_eq!(
                evidence.ledger_act_ids,
                vec![format!("ledger_act:design_decided:{}", item.id)]
            );
        }

        #[test]
        fn refuses_a_design_not_yet_decided() {
            let engine = engine();
            let item = engine
                .register_design("docs/adr/0003-test.md", "Test", "summary", Some("agent-a"))
                .unwrap();
            let task_id = claimed_task(&engine, "agent-a");

            let err = engine
                .ledger_act_evidence(&task_id, LedgerActKind::DesignDecided, &item.id, "agent-a")
                .unwrap_err();
            assert!(err.to_string().contains("has not been decided yet"));
        }

        #[test]
        fn refuses_when_the_recorded_actor_does_not_match_the_calling_agent() {
            let engine = engine();
            let item = engine
                .register_design("docs/adr/0004-test.md", "Test", "summary", Some("agent-b"))
                .unwrap();
            let task_id = claimed_task(&engine, "agent-a");

            let err = engine
                .ledger_act_evidence(
                    &task_id,
                    LedgerActKind::DesignRegistered,
                    &item.id,
                    "agent-a",
                )
                .unwrap_err();
            assert!(err.to_string().contains("does not match"));
        }

        #[test]
        fn refuses_an_unknown_act_id() {
            let engine = engine();
            let task_id = claimed_task(&engine, "agent-a");

            let err = engine
                .ledger_act_evidence(
                    &task_id,
                    LedgerActKind::DesignRegistered,
                    "design:does-not-exist",
                    "agent-a",
                )
                .unwrap_err();
            assert!(matches!(err, crate::LodestarError::NotFound(_)));
        }

        #[test]
        fn refuses_when_the_task_is_not_held_by_the_caller() {
            let engine = engine();
            let task_id = claimed_task(&engine, "agent-a");

            let err = engine
                .ledger_act_evidence(
                    &task_id,
                    LedgerActKind::DesignRegistered,
                    "design:whatever",
                    "agent-b",
                )
                .unwrap_err();
            assert!(err.to_string().contains("is not held by"));
        }

        /// The act must have happened inside the claim window: one recorded
        /// before the claim opened cannot be evidence for work the claim did
        /// not yet authorise.
        #[test]
        fn refuses_an_act_recorded_before_the_claim_opened() {
            let engine = engine();
            let path = "docs/adr/0005-test.md";
            let id = design_id_from_path(path);
            // Register directly through the store with a manufactured past
            // timestamp: the facade always stamps `now_unix()`, which would
            // make "before the claim" a flaky race against real wall-clock time.
            engine
                .store
                .register_design_item(&id, path, "Test", "summary", Some("agent-a"), 1)
                .unwrap();
            let task_id = claimed_task(&engine, "agent-a");

            let err = engine
                .ledger_act_evidence(&task_id, LedgerActKind::DesignRegistered, &id, "agent-a")
                .unwrap_err();
            assert!(err.to_string().contains("before the claim opened"));
        }
        /// ADR-0144. Superseding a clause is the only way governing intent
        /// changes, and it was the one act that could never be proved: the
        /// write recorded which version replaced the clause and a free-form
        /// reason, but no actor -- so `ledger_act_evidence` had nothing to
        /// verify against the claiming agent and ADR-0110 correctly excluded
        /// the variant. An agent whose whole task was to retire a clause had
        /// no honest completion path and routed to human review every time.
        #[test]
        fn superseding_a_clause_is_evidence_for_the_agent_who_did_it() {
            let engine = engine();
            let goal = engine
                .define_goal(GoalKind::Objective, "Ship", "ship it", None)
                .unwrap();
            let task_id = claimed_task(&engine, "agent-a");

            engine
                .supersede_goal(&goal.id, "ship it, carefully", "learned more", "agent-a")
                .unwrap();

            // The act is recorded on the RETIRED clause, not its replacement:
            // the new version records why it was written, the old one records
            // who retired it.
            let evidence = engine
                .ledger_act_evidence(&task_id, LedgerActKind::GoalSuperseded, &goal.id, "agent-a")
                .unwrap();
            assert_eq!(
                evidence.ledger_act_ids,
                vec![format!("ledger_act:goal_superseded:{}", goal.id)]
            );
            assert!(evidence.changed_node_ids.is_empty());
        }

        /// A ledger act proves who performed it, not who may claim credit for
        /// it -- the same rule the other four kinds enforce.
        #[test]
        fn another_agents_supersession_is_not_evidence_for_this_one() {
            let engine = engine();
            let goal = engine
                .define_goal(GoalKind::Objective, "Ship", "ship it", None)
                .unwrap();
            engine
                .supersede_goal(&goal.id, "ship it, carefully", "learned more", "agent-b")
                .unwrap();
            let task_id = claimed_task(&engine, "agent-a");

            let err = engine
                .ledger_act_evidence(&task_id, LedgerActKind::GoalSuperseded, &goal.id, "agent-a")
                .unwrap_err();
            assert!(
                err.to_string().contains("does not match"),
                "expected an actor-mismatch refusal, got: {err}"
            );
        }

        /// The honest floor. A clause retired before ADR-0144 has no recorded
        /// actor, and the claiming agent must never be accepted as a stand-in
        /// -- that is exactly the fabricated attribution ADR-0110 refused to
        /// build. The refusal names the reason so the reader is not left
        /// guessing whether the id was wrong.
        #[test]
        fn a_supersession_recorded_before_the_actor_existed_is_refused_not_attributed() {
            let engine = engine();
            let goal = engine
                .define_goal(GoalKind::Objective, "Ship", "ship it", None)
                .unwrap();
            engine
                .supersede_goal(&goal.id, "ship it, carefully", "learned more", "agent-a")
                .unwrap();
            // Exactly what a pre-ADR-0144 row looks like: superseded, with the
            // replacement recorded, and no actor.
            engine
                .store()
                .clear_supersession_actor_for_test(&goal.id)
                .unwrap();
            let task_id = claimed_task(&engine, "agent-a");

            let err = engine
                .ledger_act_evidence(&task_id, LedgerActKind::GoalSuperseded, &goal.id, "agent-a")
                .unwrap_err();
            assert!(
                err.to_string().contains("no recorded supersession"),
                "expected a refusal naming the missing attribution, got: {err}"
            );
        }

        /// An active clause has no supersession act at all. Distinct from the
        /// case above only in cause; both must refuse rather than invent one.
        #[test]
        fn an_active_clause_is_not_a_supersession_act() {
            let engine = engine();
            let goal = engine
                .define_goal(GoalKind::Objective, "Ship", "ship it", None)
                .unwrap();
            let task_id = claimed_task(&engine, "agent-a");

            let err = engine
                .ledger_act_evidence(&task_id, LedgerActKind::GoalSuperseded, &goal.id, "agent-a")
                .unwrap_err();
            assert!(err.to_string().contains("no recorded supersession"));
        }

        /// A goal id that names nothing is a NotFound, not a missing-actor
        /// error: the two send the reader to different places.
        #[test]
        fn an_unknown_goal_id_is_not_found_rather_than_unattributed() {
            let engine = engine();
            let task_id = claimed_task(&engine, "agent-a");

            let err = engine
                .ledger_act_evidence(
                    &task_id,
                    LedgerActKind::GoalSuperseded,
                    "goal:never-existed",
                    "agent-a",
                )
                .unwrap_err();
            assert!(
                err.to_string().contains("goal:never-existed"),
                "expected the unknown id named, got: {err}"
            );
        }
    }
}
